+    elsif v_rel.status = 'closed' then
+        raise exception 'RELEASE_CLOSED';
+    elsif v_rel.status = 'exhausted' or v_rel.paid_count >= v_rel.max_claims or v_rel.remaining_credits < v_rel.reward_per_claim then
