+    select credits, coalesce(is_locked, false)
+    into v_tester_credits, v_tester_is_locked
+    from public.profiles
+    where id = v_caller_id
+    for update;
+
+    if v_tester_is_locked then
+        raise exception 'USER_LOCKED';
+    end if;
