+        v_tester_credits
+    )
+    returning id into v_credit_log_id;
+
+    insert into public.app_update_claims (
+        release_id,
+        tester_id,
+        ordinal,
+        observed_version_code,
+        reward_credits,
+        confirmed_at,
+        credit_log_id
+    ) values (
