+        v_caller_id,
+        v_next_ordinal,
+        p_observed_version_code,
+        v_rel.reward_per_claim,
+        now(),
+        v_credit_log_id
+    );
+
+    insert into public.app_update_financial_events (
+        release_id, event_type, amount, tester_id, credit_log_id, operation_id
+    ) values (
+        v_rel.id, 'payout', v_rel.reward_per_claim, v_caller_id, v_credit_log_id, p_client_operation_id
+    );
