+        'release_status', v_new_status,
+        'receipt', jsonb_build_object(
+            'ordinal', v_next_ordinal,
+            'reward_credits', v_rel.reward_per_claim,
+            'confirmed_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
+        )
+    );
+end;
+$function$;
